import{existsSync,renameSync}from"node:fs";import{join}from"node:path";const files=["pwa-64x64.png","pwa-192x192.png","pwa-512x512.png","maskable-icon-512x512.png","apple-touch-icon-180x180.png","favicon.ico"],srcDir=join(process.cwd(),"public","images"),dstDir=join(process.cwd(),"public");let moved=0;for(const o of files){const n=join(srcDir,o),i=join(dstDir,o);existsSync(n)&&(renameSync(n,i),console.log(`✓ Moved ${o} to public/`),moved++)}console.log(`\n✅ ${moved} files moved to public/`);